import{z as o,x as A,o as r,c as d,q as n,j as l,D as t,d as E,s,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"能力涌现之争","description":"","frontmatter":{"title":"能力涌现之争","date":"2026-09-27T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/emergent-abilities.md","filePath":"llm/emergent-abilities.md","lastUpdated":1791413859000}'),p={name:"llm/emergent-abilities.md"};function m(g,a,c,D,f,h){const i=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=n('<h1 id="能力涌现之争" tabindex="-1">能力涌现之争 <a class="header-anchor" href="#能力涌现之争" aria-label="Permalink to &quot;能力涌现之争&quot;">​</a></h1><div class="epigraph"><p>能力在某个规模「突然」出现？先看坐标轴：换一把非线性尺子，涌现的悬崖常被抹成斜坡。</p><footer>—— 据 Wei et al.「Emergent Abilities of Large Language Models」(2022)；Schaeffer et al.「Mirage」NeurIPS 2023</footer></div><p><a href="/llm/attention-mask-padding">注意力掩码</a>管训练正确性，本课管如何解读 scaling 的成果：能力是否随规模「相变」。缺口是<strong>涌现之争</strong>——Wei 等的「突现」叙事 vs Schaeffer 等的「度量海市蜃楼」。这一课决定你读 scaling 曲线的眼力。本课不进缩放律拟合本身。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Wei et al. (2022) 收集多任务：多数任务性能随规模缓升，少数任务（多步算术、词序辨识）在某个规模前停在随机水平、之后陡升——「涌现」。Schaeffer et al. (2023) 反驳：把指标从 Exact Match 换成 Token Edit Distance，同一批陡升变平滑斜坡。缺口：<strong>突兀是能力的属性，还是度量的属性？</strong></p><p><span class="marginnote">术语翻译：涌现（emergence）= 小模型无此能力、大模型不可预测地获得；海市蜃楼（mirage）= 阶跃由非线性/不连续的评测指标人为制造；Brier score = 概率化连续指标，把「对错」还原为「置信度离真值的距离」。</span></p><p><span class="marginnote">数字实例：3 位数乘法，参数 10⁹ 之前 Exact Match 恒 0%，10¹⁰ 后跳到 40%——「涌现」。同一模型换 token-level edit distance：0.9 → 0.7 → 0.5 平滑下降。原因：多步乘法答对需要 10+ 个 token 全对，EM 是这些子步骤的<strong>连乘</strong>，子能力线性提升 × 连乘 = 悬崖。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读曲线的三步体检。第一步<strong>查指标</strong>：是离散/非线性（EM、accuracy、pass@k）还是连续/线性（edit distance、log-likelihood、Brier）？第二步<strong>查随机基线</strong>：k 选一任务的基线是 1/k，模型「停在随机水平」可能只是指标 saturate 的另一面；第三步<strong>查平滑替代</strong>：同一能力找连续代理重画一遍——陡崖消失即为度量伪影，陡崖保留才值得理论解释。</p>',9)),(r(),l(B,null,{default:t(()=>[s(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%83%BD%E5%8A%9B-%E8%A7%84%E6%A8%A1%E6%9B%B2%E7%BA%BF%22%5D%20--%3E%20B%7B%22%E6%8C%87%E6%A0%87%E6%98%AF%E7%A6%BB%E6%95%A3%2F%E8%BF%9E%E4%B9%98%3F%22%7D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20C%5B%22%E6%8D%A2%E8%BF%9E%E7%BB%AD%E4%BB%A3%E7%90%86%E9%87%8D%E7%94%BB%22%5D%0A%20%20C%20--%3E%7C%22%E5%8F%98%E5%B9%B3%E6%BB%91%22%7C%20D%5B%22%E5%BA%A6%E9%87%8F%E6%B5%B7%E5%B8%82%E8%9C%83%E6%A5%BC%22%5D%0A%20%20C%20--%3E%7C%22%E4%BB%8D%E9%99%A1%E5%B3%AD%22%7C%20E%5B%22%E7%9C%9F%E6%B6%8C%E7%8E%B0%E5%80%99%E9%80%89%22%5D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20E%0A%20%20E%20--%3E%20F%5B%22%E6%9F%A5%E9%9A%8F%E6%9C%BA%E5%9F%BA%E7%BA%BF%E4%B8%8E%E9%A5%B1%E5%92%8C%22%5D%0A%20%20F%20--%3E%20G%5B%22%E5%86%8D%E5%81%9A%E7%90%86%E8%AE%BA%E5%BD%92%E5%9B%A0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：考试只报「及格/不及格」——补课从 59 分涨到 61 分像「突然开窍」；改报分数，成绩是从 40 到 85 的斜坡。涌现之争一半是「只发及格证」的度量选择问题。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[E("数学机制："),e("strong",null,"连乘指标的阶跃是子任务可靠性的几何效应"),E("——若答案需要 \\(k\\) 步全对，单步正确率 \\(p\\) 线性升时最终正确率 \\(p^k\\) 呈 S 型陡升；\\(k\\) 越大（任务越长越复合），悬崖越峭。这不是模型能力的相变，是「复合任务把渐进提升非线性放大」。真正的涌现候选（如果存在）应满足：换连续指标后仍陡、且在预训练损失（而非任务指标）上无先兆。Schaeffer 的判语「emergence is a mirage」针对的多数是第一类；Grokking 之类的训练动力学相变则是另一回事——别混为一谈。")],-1)),(r(),l(B,null,{default:t(()=>[s(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E6%82%AC%E5%B4%96%E4%BB%8E%E5%93%AA%E6%9D%A5%3F%22%7D%20--%3E%20R%5B%22k%20%E6%AD%A5%E8%BF%9E%E4%B9%98%20p%5Ek%22%5D%0A%20%20R%20--%3E%20S%5B%22p%20%E7%BA%BF%E6%80%A7%E5%8D%87%20%E2%86%92%20%E7%BB%93%E6%9E%9C%20S%20%E5%9E%8B%22%5D%0A%20%20S%20--%3E%20T%5B%22%E5%A4%8D%E5%90%88%E4%BB%BB%E5%8A%A1%E6%94%BE%E5%A4%A7%E6%B8%90%E8%BF%9B%22%5D%0A%20%20U%7B%22%E5%A6%82%E4%BD%95%E8%A3%81%E5%86%B3%3F%22%7D%20--%3E%20V%5B%22%E8%BF%9E%E7%BB%AD%E6%8C%87%E6%A0%87%E9%87%8D%E7%94%BB%22%5D%0A%20%20V%20--%3E%7C%22%E5%9D%A1%22%7C%20W%5B%22%E5%BA%A6%E9%87%8F%E4%BC%AA%E5%BD%B1%22%5D%0A%20%20V%20--%3E%7C%22%E5%B4%96%22%7C%20X%5B%22%E5%80%BC%E5%BE%97%E5%BD%92%E5%9B%A0%E7%9A%84%E5%80%99%E9%80%89%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">常见误区：把「涌现」当投资/立项依据——「能力随时可能出现」的叙事不可证伪；工程上应按连续指标做外推预算。反向误区：全盘宣布「涌现皆幻影」——度量伪影解释陡崖，不解释「为什么这段基线如此低」，能力本身的存在性是另一问题。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>适用判定矩阵：任务复合度越高（多步推理、代码一次通过），连乘效应越强，「涌现」叙事越可疑；单步感知任务（翻译质量）从来都是平滑的。跨模型比较的坑：不同家族的 tokenizer/预训配比不同，「同规模」不可比，涌现点本身不可迁移。实践守则：报告能力曲线时同时给离散指标与连续代理；用缩放律外推时用连续量；立项叙事避免「突然出现」而用「在 X 预算下达到 Y 可靠性」。与<a href="/llm/semantic-uncertainty">语义熵与幻觉检测</a>的衔接：连续化的置信度量不仅平反涌现，也是幻觉检测的原料——同一把尺子。</p><p><span class="marginnote">直觉类比：多米诺骨牌推倒 100 张——「能不能全倒」是 0/1 的悬崖，但每张骨牌的稳定性是连续变量；先问「有多少张其实没立稳」（连续代理），再惊叹「为什么第 87 张一倒全倒」（连乘放大）。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>陡崖 = 连乘指标 \\(p^k\\) 对线性提升的几何放大，多为度量伪影。</li><li>三步体检：查指标离散性、换连续代理、查随机基线。</li><li>「涌现」叙事不可作立项依据；连续指标才是外推语言。</li><li>出处：Wei et al. 2022；Schaeffer–Miranda–Koyejo「Mirage」NeurIPS 2023；Ganguli et al. 可预测性讨论。</li></ul>',6))])}const k=o(p,[["render",m]]);export{u as __pageData,k as default};
